"""TC-U01 のテスト（crates/tensorcheck/tests/typelevel.rs）を生成する。

-20〜20 のすべての組について、型レベルの整数の足し算・引き算が、ふつうの整数の計算と
一致することを、コンパイル時の assert で確かめる。掛け算は -4〜4 の倍率で確かめる。
"""

from pathlib import Path


def name(v: int) -> str:
    return "Z0" if v == 0 else (f"P{v}" if v > 0 else f"N{-v}")


lines = [
    "//! TC-U01: type-level integer arithmetic (generated by scripts/gen_typelevel_tests.py).",
    "",
    "#![allow(clippy::erasing_op, clippy::identity_op)]",
    "",
    "use tensorcheck::utility::typelevel::*;",
    "",
]
for a in range(-20, 21):
    for b in range(-20, 21):
        if abs(a + b) <= 20:
            lines.append(f"const _: () = assert!(<<{name(a)} as IntAdd<{name(b)}>>::Out as Int>::VALUE == {a + b});")
        if abs(a - b) <= 20:
            lines.append(f"const _: () = assert!(<<{name(a)} as IntSub<{name(b)}>>::Out as Int>::VALUE == {a - b});")
for a in range(-5, 6):
    for k in range(-4, 5):
        if abs(a * k) <= 20:
            lines.append(f"const _: () = assert!(<<{name(a)} as IntMul<{name(k)}>>::Out as Int>::VALUE == {a * k});")
lines += [
    "",
    "#[test]",
    "fn type_level_integers_compile() {",
    "    // The assertions above run at compile time; reaching this test means they passed.",
    "    assert_eq!(<P20 as Int>::VALUE, 20);",
    "    assert_eq!(<N20 as Int>::VALUE, -20);",
    "}",
    "",
]
out = Path("crates/tensorcheck/tests/typelevel.rs")
out.write_text("\n".join(lines), encoding="utf-8")
print(f"wrote {out} ({sum(1 for l in lines if l.startswith('const'))} assertions)")
